import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { useEffect } from 'react';
import { GanttComponent, Inject, Selection, ColumnsDirective, ColumnDirective, VirtualScroll } from '@syncfusion/ej2-react-gantt';
import { DataManager, WebApiAdaptor } from '@syncfusion/ej2-data';

const LoadOnDemand = () => {
    const dataSource = new DataManager({
        url: 'https://services.syncfusion.com/react/production/api/GanttLoadOnDemand',
        adaptor: new WebApiAdaptor,
        crossDomain: true
    });
    const taskFields = {
        id: 'taskId',
        name: 'taskName',
        startDate: 'startDate',
        endDate: 'endDate',
        duration: 'duration',
        progress: 'progress',
        hasChildMapping: 'isParent',
        parentID: 'parentID'
    };
    const projectStartDate = new Date('01/02/2000');
    const projectEndDate = new Date('12/01/2002');
    return (<div className='control-pane'>
      <div className='control-section'>
        <GanttComponent id='LoadOnDemand' dataSource={dataSource} treeColumnIndex={1} taskFields={taskFields} enableVirtualization={true} loadChildOnDemand={true} height='650px' taskbarHeight={25} rowHeight={46} projectStartDate={projectStartDate} projectEndDate={projectEndDate}>
          <ColumnsDirective>
            <ColumnDirective field='taskId' width='120' headerText='Task ID'></ColumnDirective>
            <ColumnDirective field='taskName' headerText='Task Name' width='250' allowReordering={false}></ColumnDirective>
            <ColumnDirective field='startDate' headerText='Start Date' allowSorting={false}></ColumnDirective>
            <ColumnDirective field='duration' headerText='Duration' allowEditing={false}></ColumnDirective>
            <ColumnDirective field='progress' headerText='Progress' allowFiltering={false}></ColumnDirective>
          </ColumnsDirective>
          <Inject services={[Selection, VirtualScroll]}/>
        </GanttComponent>
      </div>

    </div>);
};
export default LoadOnDemand;

const root = createRoot(document.getElementById('sample'));
root.render(<LoadOnDemand />);
